package com.ruoyi.majorpilot.report.core;
import static com.ruoyi.majorpilot.report.core.ReportModels.*;
import static com.ruoyi.majorpilot.report.core.ReportTestFixtures.*;
import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.node.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;

class ReportCoreTest {
    final ReportCore core=new ReportCore(JSON);
    @Test void unsureAndNoBothReachTheValidatedBoundedReportPath(){for(String wish:List.of("UNSURE","NO")){var original=experience("AI",true);var input=new ReportInput(original.header(),original.versions(),List.of(source("AI",true,wish)),original.nextRecommendation());var c=core.compile(input);var output=core.render(input,c,core.defaultProposal(c,true),GenerationMode.AI);var bounded=output.claims().stream().filter(x->x.claimType()==ClaimType.BOUNDED_INTERPRETATION).findFirst().orElseThrow();assertTrue(bounded.text().contains(wish.equals("UNSURE")?"不确定":"不想继续"));}}
    @Test void allFrozenDsAnalyticalBranchesProduceBoundedLengthFacts(){var original=experience("DATA_SCIENCE",false);for(var golden:asset("DATA_SCIENCE","golden-private").path("cases")){var s=original.sources().getFirst();var items=new ArrayList<>(s.items());for(int i=0;i<items.size();i++){var e=items.get(i);if(e.type().equals("VERIFIED_EXECUTION")&&e.value().path("operationKey").equals(golden.path("operationKey")))items.set(i,new EvidenceValue(e.publicId(),e.key(),e.type(),golden.path("result"),e.summary(),e.allowedClaimTypes(),e.observedAt()));}var input=new ReportInput(original.header(),original.versions(),List.of(new Source(s.majorCode(),s.studentPublicId(),s.pins(),s.snapshot(),items,null)),original.nextRecommendation());assertTrue(core.fallback(input,core.compile(input)).validation().valid());}}
    @Test void trailingJsonCannotSneakPastTheProposalParser(){var c=core.compile(experience("AI",false));String valid=JSON.valueToTree(core.defaultProposal(c,false)).toString();assertThrows(ProposalException.class,()->core.parseProposal((valid+" {}").getBytes(StandardCharsets.UTF_8)));}
    @Test void threeMajorsRenderNineSectionsWithoutStudentAnalysisOrAuditIds(){for(String major:MAJORS){var input=experience(major,false);var catalog=core.compile(input);var output=core.fallback(input,catalog);assertEquals(9,output.publicReportJson().path("sections").size());assertTrue(output.validation().valid());String raw=output.publicReportJson().toString();for(String secret:List.of("PRIVATE_SENTINEL","STUDENT_ANALYSIS","evidenceIds","snapshotId","statementKey","<script>"))assertFalse(raw.contains(secret),secret);assertFalse(raw.contains("BOUNDED_INTERPRETATION"));assertTrue(new ReportSchema(JSON).output(output.publicReportJson()));assertEquals(output.bodySha256(),core.fallback(input,catalog).bodySha256());assertTrue(output.claims().stream().filter(c->Set.of(ClaimType.OBSERVED_FACT,ClaimType.STUDENT_SELF_REPORT).contains(c.claimType())).allMatch(c->!c.evidenceIds().isEmpty()));}}
    @Test void newRulesPermitBoundedOnAiPathAndFallbackStillExcludesIt(){for(String major:MAJORS){var input=experience(major,true);var catalog=core.compile(input);var ai=core.render(input,catalog,core.defaultProposal(catalog,true),GenerationMode.AI);assertEquals(1,ai.claims().stream().filter(c->c.claimType()==ClaimType.BOUNDED_INTERPRETATION).count());assertFalse(core.fallback(input,catalog).publicReportJson().toString().contains("BOUNDED_INTERPRETATION"));assertFalse(core.validate(catalog,core.defaultProposal(catalog,true),GenerationMode.DETERMINISTIC_FALLBACK).valid());}}
    @Test void comparisonHasExactFourteenOrTwentyOneAttributedDimensions(){for(int count:List.of(2,3)){var input=comparison(count,true);var catalog=core.compile(input);var output=core.fallback(input,catalog);assertEquals(8,output.publicReportJson().path("sections").size());var common=output.publicReportJson().path("sections").get(3).path("claims");assertEquals(7*count,common.size());var pairs=new HashSet<String>();for(var c:common)assertTrue(pairs.add(c.path("dimensionKey").asText()+c.path("majorCode").asText()));assertTrue(common.toString().contains("尚无足够证据"));assertFalse(output.publicReportJson().toString().contains("BOUNDED_INTERPRETATION"));}}
    @Test void malformedOrForeignSelectionsNeverBecomeTextAndMissingCellsFail(){var input=comparison(2,true);var c=core.compile(input);var proposal=core.defaultProposal(c,true);var json=(ObjectNode)JSON.valueToTree(proposal);((ArrayNode)json.at("/sections/3/selections")).remove(0);assertFalse(core.validate(c,core.parseProposal(json.toString().getBytes(StandardCharsets.UTF_8)),GenerationMode.AI).valid());((ObjectNode)json.at("/sections/0/selections/0")).put("statementKey","foreign");assertFalse(core.validate(c,core.parseProposal(json.toString().getBytes(StandardCharsets.UTF_8)),GenerationMode.AI).valid());((ObjectNode)json.at("/sections/0/selections/0")).put("text","我编造事实");assertThrows(ProposalException.class,()->core.parseProposal(json.toString().getBytes(StandardCharsets.UTF_8)));assertThrows(ProposalException.class,()->core.parseProposal("{\"schemaVersion\":\"x\",\"schemaVersion\":\"report-proposal-v1\"}".getBytes(StandardCharsets.UTF_8)));}
    @Test void sourcesAndCatalogAreHardFailuresNotRepairable(){var input=experience("AI",false);var original=input.sources().getFirst();var invalid=new Source(original.majorCode(),id(2),original.pins(),original.snapshot(),original.items(),null);assertEquals("REPORT_SOURCE_INVALID",assertThrows(ReportInputException.class,()->core.compile(new ReportInput(input.header(),input.versions(),List.of(invalid),input.nextRecommendation()))).code);var catalog=core.compile(input);var forged=new Catalog(catalog.reportType(),catalog.inputSha256(),catalog.claimRuleVersion(),catalog.entries(),"0".repeat(64));assertThrows(ReportInputException.class,()->core.fallback(input,forged));var item=original.items().stream().filter(i->i.type().equals("STUDENT_ANALYSIS")).findFirst().orElseThrow();var items=new ArrayList<>(original.items());items.set(items.indexOf(item),new EvidenceValue(item.publicId(),item.key(),item.type(),item.value(),item.summary(),List.of("OBSERVED_FACT"),item.observedAt()));var analysis=new Source(original.majorCode(),original.studentPublicId(),original.pins(),original.snapshot(),items,null);assertThrows(ReportInputException.class,()->core.compile(new ReportInput(input.header(),input.versions(),List.of(analysis),input.nextRecommendation())));}
    @Test void boundedLineageTamperingAndOldRuleEscalationReject(){var input=experience("AI",true);var s=input.sources().getFirst();var items=new ArrayList<>(s.items());var d=items.getLast();var value=(ObjectNode)d.value();value.put("continueSimilarWork","NO");items.set(items.size()-1,new EvidenceValue(d.publicId(),d.key(),d.type(),value,d.summary(),d.allowedClaimTypes(),d.observedAt()));var bad=new Source(s.majorCode(),s.studentPublicId(),s.pins(),s.snapshot(),items,null);assertThrows(ReportInputException.class,()->core.compile(new ReportInput(input.header(),input.versions(),List.of(bad),input.nextRecommendation())));var snap=s.snapshot();var old=new SnapshotRef(snap.snapshotId(),snap.status(),snap.studentPublicId(),snap.runId(),snap.taskVersionId(),snap.decisionProfileId(),snap.closedInputSha256(),snap.snapshotSha256(),"evidence-v2","evidence-v2");var oldSource=new Source(s.majorCode(),s.studentPublicId(),s.pins(),old,s.items(),null);assertThrows(ReportInputException.class,()->core.compile(new ReportInput(input.header(),input.versions(),List.of(oldSource),input.nextRecommendation())));}
    @Test void modelInputContainsOnlyRenderedCatalogAndAValidCompleteProposal(){var input=comparison(3,true);var catalog=core.compile(input);var model=core.modelInput(catalog);String raw=model.content().toString();for(String denied:List.of("PRIVATE_SENTINEL","profileSha256","snapshotId","studentPublicId","evidenceIds","sourceEvidenceKeys","reflectionNote"))assertFalse(raw.contains(denied),denied);var proposal=core.parseProposal(model.content().path("completeValidProposal").toString().getBytes(StandardCharsets.UTF_8));assertTrue(core.validate(catalog,proposal,GenerationMode.AI).valid());}
    @Test void sameOutputSchemaRejectsUnknownFieldsCoercionAndLinks(){var input=experience("AI",false);var out=(ObjectNode)core.fallback(input,core.compile(input)).publicReportJson();out.put("versionNo","1");assertThrows(ReportInputException.class,()->core.validatePublic(out));out.put("versionNo",1).put("hidden","x");assertThrows(ReportInputException.class,()->core.validatePublic(out));out.remove("hidden");((ObjectNode)out.at("/sections/0/claims/0")).put("text","https://evil.test");assertThrows(ReportInputException.class,()->core.validatePublic(out));}
    @Test void optionalGoldenExportPrintsSyntheticValidatedOutputOnly(){if(!Boolean.getBoolean("majorpilot.report.goldenExport"))return;var examples=JSON.createObjectNode();for(String major:MAJORS){var input=experience(major,true);var catalog=core.compile(input);examples.set(major.toLowerCase(java.util.Locale.ROOT),core.render(input,catalog,core.defaultProposal(catalog,true),GenerationMode.AI).publicReportJson());examples.set(major.toLowerCase(java.util.Locale.ROOT)+"-fallback",core.fallback(input,catalog).publicReportJson());}for(int count:List.of(2,3)){var input=comparison(count,true);var catalog=core.compile(input);examples.set("comparison-"+count,core.render(input,catalog,core.defaultProposal(catalog,true),GenerationMode.AI).publicReportJson());}System.out.println("REPORT_GOLDEN_BASE64="+Base64.getEncoder().encodeToString(examples.toString().getBytes(StandardCharsets.UTF_8)));}
}
